function displayNoteSummary(note) {
  var text = note && note.summary ? String(note.summary).replace(/\s+/g, ' ').trim() : '';
  if (!text && note && note.content) {
    text = String(note.content).replace(/\s+/g, ' ').trim();
  }
  if (!text) return '';
  if (isNoteSummaryBoilerplate(text)) {
    text = extractAnswerEssence(text) || text;
  }
  return text.length > 120 ? text.slice(0, 117) + '…' : text;
}

function isNoteSummaryBoilerplate(text) {
  return /思考完成|本轮内部路由|DeepSeek-|已命中\s*\d+\s*段|引用段落|查看原文|知识库：/.test(text);
}

function extractAnswerEssence(assistantText) {
  var t = String(assistantText || '').replace(/\s+/g, ' ').trim();
  if (!t) return '';
  var labelIdx = t.indexOf('简要结论：');
  if (labelIdx >= 0) {
    t = t.slice(labelIdx + 5).trim();
    var stop = t.indexOf('针对「');
    if (stop > 0) t = t.slice(0, stop).trim();
    if (t) return t.slice(0, 80);
  }
  t = t.replace(/思考完成/g, '');
  t = t.replace(/本轮内部路由[^。！？!?]*[。！？!?]?/g, '');
  t = t.replace(/结合[^。！？!?]*生成回答[。！？!?]?/g, '');
  t = t.replace(/知识库：[^。！？!?]*[。！？!?]?/g, '');
  t = t.replace(/已命中\s*\d+\s*段/g, '');
  t = t.replace(/引用段落|查看原文/g, '');
  t = t.replace(/\s+/g, ' ').trim();
  var sentence = t.match(/[^。！？!?]+[。！？!?]?/);
  if (sentence && sentence[0].length >= 8) return sentence[0].trim().slice(0, 80);
